<?php
function adjustment_access(){if(!adjustments_ready())throw new Exception('Run upgrade_adjustments_reports.php first.');if(!can_action('upload_inventory_count'))throw new Exception('Auditor, Operations Lead or Admin access is required for inventory adjustment requests.');}
function adjustment_event($id,$type,$details){$b=count_batch($id);db()->prepare('INSERT INTO count_review_events(batch_id,event_type,revision,details_json,user_id) VALUES(?,?,?,?,?)')->execute([$id,$type,$b['revision'],json_encode($details),current_user()['id']]);}
function adjustment_is_new($id){return in_array(count_batch($id)['workflow_version']??'',['5.4.0','5.4.29'],true);}
function adjustment_rule(){return ['version'=>'ADJ-20-40-40-v1','percentages'=>['Lazada'=>20,'Shopee'=>40,'TikTok'=>40],'rounding'=>'Largest remainder; equal remainders: Shopee, TikTok, Lazada','tie_priority'=>['Shopee','TikTok','Lazada']];}
function adjustment_rounding($total,$rule){if($total<0)throw new Exception('Verified sellable count cannot be negative.');$lines=[];$sum=0;foreach($rule['percentages'] as $pl=>$pct){$raw=$total*$pct/100;$floor=(int)floor($raw);$lines[$pl]=['percent'=>$pct,'raw'=>$raw,'floor'=>$floor,'remainder'=>round($raw-$floor,8),'extra'=>0,'final'=>$floor];$sum+=$floor;}$rank=array_keys($lines);usort($rank,function($a,$b)use($lines,$rule){$c=$lines[$b]['remainder']<=>$lines[$a]['remainder'];return $c?:array_search($a,$rule['tie_priority'],true)<=>array_search($b,$rule['tie_priority'],true);});$remaining=$total-$sum;for($i=0;$i<$remaining;$i++){$pl=$rank[$i%3];$lines[$pl]['extra']++;$lines[$pl]['final']++;}return $lines;}
function adjustment_create($input){return final_count_create($input);}
function adjustment_create_recount_legacy($input){adjustment_access();$date=process_date($input['count_date']??date('Y-m-d'));if($date!==date('Y-m-d'))throw new Exception('Create a count snapshot on the actual count date (today). Use Daily Movement for historical dates.');require_open_inventory_date($date);
 return process_transaction(function()use($input,$date){$id=count_create_snapshot_legacy($input);$now=date('Y-m-d H:i:s');db()->prepare('UPDATE inventory_count_batches SET workflow_version=?,cutoff_at=?,rule_json=? WHERE id=?')->execute(['5.4.0',$now,json_encode(adjustment_rule()),$id]);foreach(count_lines($id) as $l){$c=inventory_condition_balances($l['product_id']);if(min($c['packaging'],$c['damaged'],$c['other'])<0||array_sum($c)!==(int)$l['on_hand'])throw new Exception('Restricted conditions need reconciliation before counting '.$l['master_sku'].'.');$q=db()->prepare('SELECT b.batch_ref FROM inventory_count_batches b JOIN inventory_count_lines x ON x.batch_id=b.id WHERE x.product_id=? AND b.id<>? AND b.workflow_version=? AND b.status NOT IN (\'Applied\',\'Cancelled\',\'Reversed\') LIMIT 1');$q->execute([$l['product_id'],$id,'5.4.0']);if($ref=$q->fetchColumn())throw new Exception('An open count already includes '.$l['master_sku'].' ('.$ref.'). Complete or cancel it first.');db()->prepare('UPDATE inventory_count_lines SET snapshot_conditions=? WHERE id=?')->execute([json_encode($c),$l['id']]);}if(count(count_lines($id))>9900)throw new Exception('Limit each count sheet to 9,900 products.');adjustment_event($id,'Snapshot created',['cutoff'=>$now,'date'=>$date,'rule'=>adjustment_rule()]);return $id;});
}
function adjustment_export($id,$path,$stage='First'){if(final_count_is($id))return final_count_export($id,$path);$b=count_batch($id);if(!in_array($stage,['First','Recount'],true))throw new Exception('Invalid count stage.');$rows=[];foreach(count_lines($id) as $l)$rows[]=[$l['master_sku'],$l['product_name'],(int)$l['on_hand'],'','','','',''];report_write_xlsx($path,'Physical Inventory Count',['Master SKU','Product Description','On Hand','Actual Good','Actual Packaging','Actual Damaged','Actual Other Restricted','Remarks'],$rows,['Batch'=>$b['batch_ref'],'Revision'=>(int)$b['revision'],'Stage'=>$stage,'Cutoff'=>$b['cutoff_at'],'Count Date'=>$b['count_date'],'Instructions'=>'Fill all four condition counts for counted rows; use 0 for zero. Blank rows are not counted. Remarks required for discrepancies. Keep identifiers and On Hand unchanged.'],[3,4,5,6,7]);}
function adjustment_check_open($id,$lock=false){$q=db()->prepare('SELECT * FROM inventory_count_batches WHERE id=?'.($lock?' FOR UPDATE':''));$q->execute([$id]);$b=$q->fetch();if(!$b||$b['workflow_version']!=='5.4.0'||in_array($b['status'],['Applied','Cancelled','Reversed'],true))throw new Exception('This adjustment is closed or uses the legacy workflow.');return $b;}
function adjustment_check_stocks($id){foreach(count_lines($id) as $l){$q=db()->prepare('SELECT active FROM products WHERE id=? FOR UPDATE');$q->execute([$l['product_id']]);if(!$q->fetchColumn())throw new Exception('Product is inactive: '.$l['master_sku']);if(!hash_equals($l['stock_signature'],count_stock_signature($l['product_id'])))throw new Exception('Stock changed after cutoff for '.$l['master_sku'].'. Cancel this count, create a fresh snapshot and recount.');check_platform_alignment($l['product_id']);}}
function adjustment_upload($id,$rows,$filename,$fileHash=null,$storedPath=null){if(final_count_is($id))return final_count_upload($id,$rows,$filename,$fileHash,$storedPath,$_POST);adjustment_access();return process_transaction(function()use($id,$rows,$filename,$fileHash,$storedPath){$b=adjustment_check_open($id,true);if($b['status']==='Awaiting Approval')throw new Exception('Return this adjustment for review before uploading another file.');$hash=$fileHash??hash('sha256',json_encode($rows));$q=db()->prepare('SELECT id FROM count_upload_evidence WHERE batch_id=? AND file_hash=?');$q->execute([$id,$hash]);if($q->fetchColumn())throw new Exception('This exact file was already uploaded to this count. Open its history; download the latest sheet for corrections.');
 $meta=[];foreach($rows as $r)if(isset($r[0],$r[1]))$meta[norm($r[0])]=$r[1];$errors=[];$stage=trim($meta['stage']??'');if(($rows[0][0]??'')!=='Physical Inventory Count'||($meta['batch']??'')!==$b['batch_ref'])$errors[]='Wrong count session. Download its original sheet.';if((string)($meta['revision']??'')!==(string)$b['revision'])$errors[]='Stale file revision. Download the latest sheet.';if(($meta['cutoff']??'')!==$b['cutoff_at'])$errors[]='Cutoff identifier was changed.';if(!in_array($stage,['First','Recount'],true))$errors[]='Invalid count stage.';
 $headers=['Master SKU','Product Description','On Hand','Actual Good','Actual Packaging','Actual Damaged','Actual Other Restricted','Remarks'];$hr=find_header_row($rows,[$headers]);$known=[];foreach(count_lines($id) as $l)$known[$l['master_sku']]=$l;$values=[];$seen=[];
 if($hr===null)$errors[]='Required four-condition headers are missing.';else{$col=array_flip(array_map('norm',$rows[$hr]));foreach(array_slice($rows,$hr+1) as $i=>$r){if(!array_filter($r,fn($v)=>trim((string)$v)!==''))continue;$n=$hr+$i+2;$sku=trim($r[$col['master sku']]??'');if(!isset($known[$sku])){$errors[]="Row $n: unknown Master SKU.";continue;}if(isset($seen[$sku])){$errors[]="Row $n: duplicate SKU.";continue;}$seen[$sku]=true;$l=$known[$sku];if(trim($r[$col['product description']]??'')!==$l['product_name'])$errors[]="Row $n: description changed.";$on=(string)($r[$col['on hand']]??'');if(!is_numeric($on)||(float)$on!==(float)$l['on_hand'])$errors[]="Row $n: On Hand changed.";$vs=[];foreach(['Actual Good','Actual Packaging','Actual Damaged','Actual Other Restricted'] as $h)$vs[]=trim((string)($r[$col[norm($h)]]??''));if(!array_filter($vs,fn($v)=>$v!==''))continue;$valid=true;foreach($vs as $v)if(!preg_match('/^\d{1,8}$/D',$v))$valid=false;if(!$valid){$errors[]="Row $n: enter all four conditions as non-negative whole numbers; use 0 for zero.";continue;}$v=array_combine(['good','packaging','damaged','other'],array_map('intval',$vs));$remark=trim((string)($r[$col['remarks']]??''));$snap=json_decode($l['snapshot_conditions'],true);if($v!==$snap&&strlen($remark)<3)$errors[]="Row $n: discrepancy remarks are required.";if($stage==='Recount'&&$l['actual_count']===null)$errors[]="Row $n: recount cannot add a previously uncounted product.";$values[$l['id']]=[$v,$remark];}}
 if(!$values&&!$errors)$errors[]='No counts entered. Blank is not zero.';if($stage==='Recount')foreach($known as $l)if($l['actual_count']!==null&&!isset($values[$l['id']]))$errors[]='Recount required for '.$l['master_sku'];
 if(!$errors)adjustment_check_stocks($id);
 db()->prepare('INSERT INTO count_upload_evidence(batch_id,file_hash,filename,stored_path,stage,revision,user_id,errors_json) VALUES(?,?,?,?,?,?,?,?)')->execute([$id,$hash,basename($filename),$storedPath,$stage,(int)$b['revision'],current_user()['id'],json_encode($errors)]);
 if(!$errors){if($stage==='First')db()->prepare('UPDATE inventory_count_lines SET actual_count=NULL,variance=NULL,actual_good=NULL,actual_damaged=NULL,recount_json=NULL,recount_by=NULL,recount_at=NULL,final_conditions=NULL,remarks=NULL WHERE batch_id=?')->execute([$id]);foreach($values as $lid=>[$v,$remark]){if($stage==='First')db()->prepare('UPDATE inventory_count_lines SET actual_count=?,variance=?-on_hand,actual_good=?,actual_damaged=?,remarks=? WHERE id=? AND batch_id=?')->execute([array_sum($v),array_sum($v),$v['good'],$v['damaged'],json_encode(['first'=>$v,'first_remarks'=>$remark]),$lid,$id]);else{db()->prepare('UPDATE inventory_count_lines SET recount_json=?,recount_by=?,recount_at=NOW(),final_conditions=NULL WHERE id=? AND batch_id=?')->execute([json_encode(['counts'=>$v,'remarks'=>$remark]),current_user()['id'],$lid,$id]);}}}
 $status=$errors?'Error':($stage==='Recount'?'Recounted':'Recount Required');db()->prepare('UPDATE inventory_count_batches SET status=?,filename=?,error_json=?,revision=revision+1,upload_hash=?,review_digest=NULL,reviewed_by=NULL,reviewed_name=NULL,reviewed_role=NULL,reviewed_at=NULL WHERE id=?')->execute([$status,basename($filename),json_encode($errors),$hash,$id]);adjustment_event($id,$errors?'Upload errors':$stage.' upload',['errors'=>$errors,'filename'=>basename($filename),'hash'=>$hash,'lines'=>count($values)]);audit('Inventory count upload','Inventory Count',$b['batch_ref'],$stage.'; '.count($values).' counts; '.count($errors).' errors. No stock changed.');return $errors;});}
function adjustment_plan($id){if(final_count_is($id))return final_count_plan($id);$b=count_batch($id);$rule=json_decode($b['rule_json'],true);$plans=[];foreach(count_lines($id) as $l){if($l['actual_count']===null)continue;$rc=json_decode($l['recount_json']??'null',true);if(!$rc)throw new Exception('Recount is required for '.$l['master_sku'].'.');$final=$rc['counts'];$snap=json_decode($l['snapshot_conditions'],true);$round=adjustment_rounding($final['good'],$rule);$before=[];$after=[];$platformDelta=[];foreach(['Lazada','Shopee','TikTok'] as $pl){$before[$pl]=platform_qty($pl,$l['product_id']);$after[$pl]=$round[$pl]['final'];$platformDelta[$pl]=$after[$pl]-$before[$pl];}$plans[]=['line_id'=>$l['id'],'product_id'=>$l['product_id'],'sku'=>$l['master_sku'],'product'=>$l['product_name'],'snapshot'=>$snap,'first'=>json_decode($l['remarks'],true)['first'],'recount'=>$final,'remarks'=>$rc['remarks'],'physical_delta'=>array_sum($final)-array_sum($snap),'good_delta'=>$final['good']-$snap['good'],'before_platforms'=>$before,'final_platforms'=>$after,'platform_changes'=>$platformDelta,'rounding'=>$round];}if(!$plans)throw new Exception('There are no counted products.');return ['batch'=>$b,'lines'=>$plans,'rule'=>$rule,'digest'=>hash('sha256',json_encode([$b['revision'],$rule,$plans]))];}
function adjustment_review($id,$reason,$reference,$revision,$ack){if(current_user()['role']!=='Admin')throw new Exception('Only an Admin can review a submitted adjustment.');if(final_count_is($id))return final_count_review($id,$revision,$ack);adjustment_access();if(!$ack)throw new Exception('Acknowledge the recount and final allocation review.');$reason=process_reason($reason);$reference=trim((string)$reference);if(strlen($reference)<3||strlen($reference)>255)throw new Exception('Supporting reference is required (3–255 characters).');return process_transaction(function()use($id,$reason,$reference,$revision){$b=adjustment_check_open($id,true);if($b['status']!=='Recounted'||(int)$revision!==(int)$b['revision'])throw new Exception('Recount or page revision changed. Review again.');require_open_inventory_date($b['count_date']);adjustment_check_stocks($id);$a=adjustment_plan($id);foreach($a['lines'] as $l)db()->prepare('UPDATE inventory_count_lines SET final_conditions=? WHERE id=?')->execute([json_encode($l['recount']),$l['line_id']]);$u=current_user();db()->prepare("UPDATE inventory_count_batches SET status='Awaiting Approval',reason=?,support_reference=?,reviewed_by=?,reviewed_name=?,reviewed_role=?,reviewed_at=NOW(),review_digest=? WHERE id=?")->execute([$reason,$reference,$u['id'],$u['name'],$u['role'],$a['digest'],$id]);adjustment_event($id,'Reviewed',['reason'=>$reason,'reference'=>$reference,'digest'=>$a['digest']]);audit('Review inventory adjustment','Inventory Count',$b['batch_ref'],'Recount checked; awaiting separate Admin approval.');});}
function adjustment_release_review($id,$reason){if(final_count_is($id))return final_count_close($id,$reason,true);adjustment_access();$reason=process_reason($reason);return process_transaction(function()use($id,$reason){$b=adjustment_check_open($id,true);if($b['status']!=='Awaiting Approval')throw new Exception('No pending approval to return.');db()->prepare("UPDATE inventory_count_batches SET status='Recounted',revision=revision+1,review_digest=NULL,reviewed_by=NULL,reviewed_name=NULL,reviewed_role=NULL,reviewed_at=NULL WHERE id=?")->execute([$id]);adjustment_event($id,'Returned for review',['reason'=>$reason,'previous_reviewer'=>$b['reviewed_name']]);});}
function adjustment_release_condition($pid,$kind,$qty,$date,$ref,$note,$asOf=null){if(!$qty)return;$q=db()->prepare('SELECT * FROM non_sellable WHERE product_id=? AND qty>0 AND reversed_by_request IS NULL AND (? IS NULL OR txn_date<=?) ORDER BY id');$q->execute([$pid,$asOf,$asOf]);$sources=[];foreach($q as $n){$k=packaging_kind($n['condition_type']);$k=$k==='packaging'?'packaging':($k==='damaged'?'damaged':'other');if($k!==$kind)continue;$left=max(0,(int)$n['qty']-release_total($n['id']));if($left){$n['available']=$left;$sources[]=$n;}}
 // Legacy releases without source links must not be guessed during adjustment.
 $q=db()->prepare('SELECT COUNT(*) FROM nonsellable_outflows o WHERE product_id=? AND qty<>0 AND NOT EXISTS(SELECT 1 FROM nonsellable_release_links l WHERE l.release_id=o.id)');$q->execute([$pid]);if($q->fetchColumn())throw new Exception('Legacy unlinked restricted releases need reconciliation before reducing '.$kind.' for product #'.$pid.'.');
 db()->prepare('INSERT INTO nonsellable_outflows(txn_date,product_id,qty,type,reference_no,remarks,user_id) VALUES(?,?,?,?,?,?,?)')->execute([$date,$pid,$qty,'Inventory Count Adjustment',$ref,$note,current_user()['id']]);$release=(int)db()->lastInsertId();foreach($sources as $n){$take=min($qty,$n['available']);if($take)db()->prepare('INSERT INTO nonsellable_release_links(release_id,non_sellable_id,qty) VALUES(?,?,?)')->execute([$release,$n['id'],$take]);$qty-=$take;if(!$qty)break;}if($qty)throw new Exception('Not enough traceable '.$kind.' stock for this count reduction.');}
function adjustment_post($id,$digest,$ack){if(final_count_is($id))return final_count_post($id,$digest,$ack);adjustment_access();if(current_user()['role']!=='Admin')throw new Exception('Admin approval required.');if(!$ack)throw new Exception('Review and acknowledge the final adjustment.');return process_transaction(function()use($id,$digest){$b=adjustment_check_open($id,true);if($b['status']!=='Awaiting Approval')throw new Exception('This count is not awaiting approval.');access_assert_admin_approval($b['created_by']);require_open_inventory_date($b['count_date']);adjustment_check_stocks($id);$a=adjustment_plan($id);if(!hash_equals($b['review_digest'],$a['digest'])||!hash_equals($a['digest'],(string)$digest))throw new Exception('Review changed. Return for review before approval.');$date=$b['count_date'];$ref=$b['batch_ref'];$uid=current_user()['id'];foreach($a['lines'] as $l){$pid=$l['product_id'];$note=$b['reason'].'; '.$b['support_reference'].'; '.$l['remarks'];$gd=$l['good_delta'];if($gd>0)db()->prepare('INSERT INTO inflows(txn_date,reference_no,product_id,source_qty,source_uom,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$date,$ref,$pid,$gd,'pc',$gd,'Inventory Count Adjustment',$note,$uid]);elseif($gd<0)db()->prepare('INSERT INTO outflows(txn_date,platform,order_id,product_id,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?)')->execute([$date,'Internal',$ref,$pid,-$gd,'Inventory Count Adjustment',$note,$uid]);
 foreach(['packaging'=>'RAW / For Packaging','damaged'=>'Damage / Leak','other'=>'Other Restricted Stocks'] as $k=>$condition){$delta=$l['recount'][$k]-$l['snapshot'][$k];if($delta>0)db()->prepare("INSERT INTO non_sellable(txn_date,platform,order_id,product_id,qty,condition_type,action_type,status,origin,sellable_deducted,remarks,user_id,packaging_state) VALUES(?,'Internal',?,?,?,?,'Count Adjustment','For Review','Inventory Count',0,?,?,?)")->execute([$date,$ref,$pid,$delta,$condition,$note,$uid,$k==='packaging'?'Pending':null]);elseif($delta<0)adjustment_release_condition($pid,$k,-$delta,$date,$ref,$note);}
 // Physical sellable variance is placed on the largest source allocation first;
 // redistribution is a distinct zero-net platform movement afterwards.
 $intermediate=$l['before_platforms'];$physicalSplit=['Lazada'=>0,'Shopee'=>0,'TikTok'=>0];if($gd>=0){$physicalSplit['Shopee']=$gd;}else{$left=-$gd;$rank=$intermediate;arsort($rank,SORT_NUMERIC);foreach($rank as $pl=>$available){$take=min($left,max(0,$available));$physicalSplit[$pl]-=$take;$left-=$take;}if($left)$physicalSplit['Shopee']-=$left;}
 foreach($physicalSplit as $pl=>$delta)if($delta){$GLOBALS['RS8_REPORT_ACTION']='Physical Adjustment';change_platform_stock($pl,$pid,$delta,$ref,$date);unset($GLOBALS['RS8_REPORT_ACTION']);$intermediate[$pl]+=$delta;}
 $redistribution=[];foreach($l['final_platforms'] as $pl=>$target){$delta=$target-$intermediate[$pl];$redistribution[$pl]=$delta;if($delta){$GLOBALS['RS8_REPORT_ACTION']='Platform Redistribution';change_platform_stock($pl,$pid,$delta,$ref,$date);unset($GLOBALS['RS8_REPORT_ACTION']);}}if(array_sum($redistribution)!==0)throw new Exception('Redistribution is not balanced.');check_platform_alignment($pid);$now=stock_row($pid);if($now['current']!==$l['recount']['good']||$now['physical']!==array_sum($l['recount']))throw new Exception('Count posting failed its stock reconciliation.');
 $posting=$l+['physical_platform_split'=>$physicalSplit,'intermediate_platforms'=>$intermediate,'redistribution'=>$redistribution];db()->prepare('UPDATE inventory_count_lines SET posting_json=? WHERE id=?')->execute([json_encode($posting),$l['line_id']]);$insert=db()->prepare('INSERT INTO adjustment_movements(batch_id,product_id,txn_date,movement_type,physical_delta,sellable_delta,platform_json,detail_json,user_id) VALUES(?,?,?,?,?,?,?,?,?)');$insert->execute([$id,$pid,$date,'Physical Adjustment',$l['physical_delta'],$gd,json_encode($physicalSplit),json_encode($posting),$uid]);$insert->execute([$id,$pid,$date,'Platform Redistribution',0,0,json_encode($redistribution),json_encode(['final'=>$l['final_platforms'],'rule'=>$a['rule'],'rounding'=>$l['rounding']]),$uid]);audit('Physical count adjustment','Product',$l['sku'],$ref.'; physical delta '.$l['physical_delta'].'; sellable delta '.$gd);audit('Platform redistribution','Product',$l['sku'],$ref.'; net physical 0; '.json_encode($redistribution).'; rule '.$a['rule']['version']);}
 $u=current_user();db()->prepare("UPDATE inventory_count_batches SET status='Applied',approved_by=?,approved_name=?,approved_role=?,applied_at=NOW() WHERE id=?")->execute([$uid,$u['name'],$u['role'],$id]);adjustment_event($id,'Approved and posted',['approver'=>$u['name'],'rule'=>$a['rule'],'products'=>count($a['lines'])]);});}
